/* ---------- Automatic rules: day 15 / day 30 / arrangement lapse ---------- */
const odTz = o => o.v ? tzOfLearner(STORE.worlds[o.v].me) : tzOfLearner(learnerById(o.lid) || {});
function finAuto() {
  const F = STORE.fin; if (!F) return;
  F.od.forEach(o => {
    const d = calDaysLate(o.due, odTz(o)), has = l => o.history.some(h => h[0].startsWith(l));
    if (o.status === 'paid' || o.status === 'discontinued') return;
    if (d >= 15 && !has('Day 15')) o.history.push(['Day 15: notified', now().toISOString()]);
    if (o.status === 'arrangement' && calDaysLate(o.arrangeDue, odTz(o)) > 0) { o.status = 'overdue'; o.history.push(['Arrangement lapsed: re-paused', now().toISOString()]); F.notifs.unshift({ to: 'all', t: 'Arrangement lapsed — access re-paused', b: o.name, at: now().toISOString(), go: 'f-overdue', unread: true }); }
    if (d >= 30 && o.status === 'overdue' && !has('Day 30')) o.history.push(['Day 30: notified + access paused', now().toISOString()]);
  });
  ['C'].forEach(v => {
    const w = STORE.worlds[v], row = w.plans.find(p => p.e === 'nvq')?.rows.find(r => r.status === 'Overdue' || (r.arrangement && r.status !== 'Paid'));
    if (!row || w.nvq.status === 'Discontinued') return;
    if (row.arrangement && w.arrangeUntil && calDaysLate(w.arrangeUntil, tzOfLearner(w.me)) > 0 && row.status !== 'Paid') { row.status = 'Overdue'; row.arrangement = false; w.arrangeUntil = null; w.accessPaused = true; w.payOverdue = { label: 'Instalment ' + row.n, amount: row.amount - row.paid, due: row.due, e: 'nvq', n: row.n }; notifyLearner(v, 'Payments', 'Access paused', 'Your payment arrangement date passed unpaid — access is paused again.', 'payments'); }
    else if (row.status === 'Overdue' && calDaysLate(row.due, tzOfLearner(w.me)) >= 30 && !w.accessPaused && !w.arrangeUntil) { w.accessPaused = true; notifyLearner(v, 'Payments', 'Access paused', `Instalment ${row.n} is 30 days overdue — access is paused until it's paid.`, 'payments'); }
  });
}
function odRows() {
  const F = STORE.fin, out = F.od.map(o => ({ ...o, src: o, days: calDaysLate(o.due, odTz(o)), access: o.status === 'discontinued' ? 'Discontinued' : o.status === 'arrangement' ? 'Restored until ' + fd(o.arrangeDue) : calDaysLate(o.due, odTz(o)) >= 30 ? 'Paused' : 'Active', remind: o.history.filter(h => h[0].startsWith('Day')).map(h => fd(h[1])).join(', ') || '—', last: (o.history[o.history.length - 1] || ['—'])[0] }));
  ['C', 'A'].forEach(v => {
    const w = STORE.worlds[v];
    w.plans.forEach(pl => pl.rows.forEach(r => {
      if (!(r.status === 'Overdue' || r.arrangement || (r.status === 'Pending' && calDaysLate(r.due, tzOfLearner(w.me)) > 0))) return;
      if (r.status === 'Paid') return;
      const days = calDaysLate(r.due, tzOfLearner(w.me));
      out.unshift({ id: 'W-' + v + pl.e + r.n, v, lid: w.me.id, name: VNAME(v), course: pl.title, batch: pl.e === 'nvq' ? (w.nvq.batch || '').split(' — ')[0] : '—', sponsor: w.me.sponsor, inst: r.n, amount: r.amount - r.paid, cur: (pl.cur || w.me.cur), due: r.due, days, status: w.enrolments.find(e => e.id === pl.e || (pl.e === 'nvq' && e.kind === 'nvq'))?.status === 'Discontinued' ? 'discontinued' : r.arrangement && w.arrangeUntil ? 'arrangement' : 'overdue', arrangeDue: w.arrangeUntil, access: w.arrangeUntil && r.arrangement ? 'Restored until ' + fd(w.arrangeUntil) : w.accessPaused ? 'Paused' : 'Active', remind: days >= 15 ? fd(D(-(days - 15))) + (days >= 30 ? ', ' + fd(D(-(days - 30))) : '') : '—', last: w.accessPaused ? 'Day 30: notified + access paused' : days >= 15 ? 'Day 15: notified' : '—', row: r, pl, history: [] });
    }));
  });
  return ADMIN.edge === 'finEmpty' ? [] : out;
}

