    if (d.consequence === 'Revoke access' && d.enrol) { const e = w.enrolments.find(x => x.id === d.enrol); if (e) { e.status = 'Discontinued'; e.reason = 'Access ended on ' + fd(now().toISOString()) + ' after a refund of ' + money(i.amount, i.cur) + '.'; } }
