function shiftDays(n) {
  const sh = iso => iso ? new Date(new Date(iso).getTime() - n * DAY).toISOString() : iso;
  STORE.fin.od.forEach(o => { o.due = sh(o.due); if (o.arrangeDue) o.arrangeDue = sh(o.arrangeDue); });
  STORE.fin.deposits.forEach(d => { d.hold = sh(d.hold); });
  [...'ABCDEF'].forEach(v => { const w = STORE.worlds[v]; w.plans.forEach(pl => pl.rows.forEach(r => { if (r.status !== 'Paid') { r.due = sh(r.due); if (r.status === 'Pending' && calDaysLate(r.due, tzOfLearner(w.me)) > 0) r.status = 'Overdue'; } })); if (w.arrangeUntil) w.arrangeUntil = sh(w.arrangeUntil); const od = w.plans.find(p => p.e === 'nvq')?.rows.find(x => x.status === 'Overdue'); if (od) w.payOverdue = { label: 'Instalment ' + od.n, amount: od.amount - od.paid, due: od.due, e: 'nvq', n: od.n }; });
  finAuto();
}
ACT.finAdvance = el => {
  let n = 15;
  if (el.dataset.d === 'arr') { const ds = STORE.fin.od.filter(o => o.status === 'arrangement').map(o => daysTo(o.arrangeDue)).concat(STORE.worlds.C.arrangeUntil ? [daysTo(STORE.worlds.C.arrangeUntil)] : []); if (!ds.length) { toast('No upcoming arrangements.', 'info'); return; } n = Math.max(...ds.filter(d => d >= 0).concat([0])) + 1; }
  shiftDays(n); render(); toast(`Demo only: advanced ${n} days. Automatic escalation rules have run.`, 'info');
};
ACT.finAisha30 = () => { const C = STORE.worlds.C, row = C.plans.find(p => p.e === 'nvq').rows.find(r => r.status === 'Overdue') || C.plans.find(p => p.e === 'nvq').rows[4]; row.status = 'Overdue'; row.due = D(-32); row.arrangement = false; C.arrangeUntil = null; C.accessPaused = false; C.payOverdue = { label: 'Instalment ' + row.n, amount: row.amount - row.paid, due: row.due, e: 'nvq', n: row.n }; finAuto(); render(); toast('Demo only: Aisha\'s instalment 5 is 32 days overdue — access paused.', 'info'); };

